def transform(grid):
    h, w = len(grid), len(grid[0])

    # Separator rows and columns are solid lines of the divider color.
    sep_color = max(set(grid[0]), key=lambda c: sum(row.count(c) for row in grid))
    sep_rows = [r for r in range(h) if all(v == sep_color for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == sep_color for r in range(h))]

    row_edges = [-1] + sep_rows + [h]
    col_edges = [-1] + sep_cols + [w]
    row_blocks = [(row_edges[i] + 1, row_edges[i + 1]) for i in range(len(row_edges) - 1)]
    col_blocks = [(col_edges[i] + 1, col_edges[i + 1]) for i in range(len(col_edges) - 1)]

    # The non-divider color occurring most often is the background;
    # the other color is the mark being counted in each block.
    colors = {}
    for row in grid:
        for v in row:
            if v != sep_color:
                colors[v] = colors.get(v, 0) + 1
    background = max(colors, key=colors.get)
    mark = min(colors, key=colors.get)

    counts = []
    for r0, r1 in row_blocks:
        row_counts = []
        for c0, c1 in col_blocks:
            row_counts.append(sum(grid[r][c] == mark
                                  for r in range(r0, r1)
                                  for c in range(c0, c1)))
        counts.append(row_counts)

    out = [[background for _ in col_blocks] for _ in row_blocks]
    for i, row_counts in enumerate(counts):
        if len(row_counts) > 1:
            high = max(row_counts)
            if row_counts.count(high) == 1 and row_counts.count(min(row_counts)) == len(row_counts) - 1:
                out[i][row_counts.index(high)] = 1
    return out

